//! Status portraits for the four crew captains.
//!
//! The embedded set is original pixel art generated by `tools/crew_originals.py` for this
//! private experiment. A different set can be dropped in without a rebuild: point
//! `SHINA_SPRITES` at a folder containing `<captain>/<Face>.png`, or add
//! `<workspace>/assets/crew` with the same layout. Each captain needs Normal, Happy,
//! Determined, Surprised, Dizzy and Sad. An incomplete set falls back to the embedded
//! artwork instead of failing startup.
use rune::{Image, ImageCache, Waker};
use std::{
    env,
    path::{Path, PathBuf},
    sync::Arc,
};

/// Display names, in the same order as the captain indices used by threads.
/// Portrait names in the captain editor describe the art, not a captain identity.
pub const PORTRAIT_NAMES: [&str; 4] = ["Copper", "Mint", "Indigo", "Gold"];
pub const CAPTAIN_NAMES: [&str; 4] = ["Ember", "Juniper", "Sable", "Pip"];
/// Folder names used by the sprite-set loader.
pub const CAPTAIN_KEYS: [&str; 4] = ["ember", "juniper", "sable", "pip"];
/// The work each captain is responsible for.
pub const CAPTAIN_ROLES: [&str; 4] = ["Platform", "Release", "Support", "Research"];
pub const CAPTAIN_ROLE_DETAIL: [&str; 4] = [
    "Architecture and implementation",
    "Release planning and validation",
    "Support investigations and fixes",
    "Long-horizon research and refactors",
];
const FACE_FILES: [&str; Face::COUNT] =
    ["Normal", "Happy", "Determined", "Surprised", "Dizzy", "Sad"];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Face {
    Normal,
    Happy,
    Determined,
    Surprised,
    Dizzy,
    Sad,
}

impl Face {
    pub const COUNT: usize = 6;
    pub fn index(self) -> usize {
        match self {
            Self::Normal => 0,
            Self::Happy => 1,
            Self::Determined => 2,
            Self::Surprised => 3,
            Self::Dizzy => 4,
            Self::Sad => 5,
        }
    }
}

type Set = [Image; Face::COUNT];

pub struct Artwork {
    crew: [Set; CAPTAIN_NAMES.len()],
    /// Head crops for tiles of 24 px and below, where the full bust is too small to read.
    small: [Set; CAPTAIN_NAMES.len()],
    pub mark: Image,
    /// The same mark with a light badge, for the dark theme.
    pub mark_dark: Image,
}

impl Artwork {
    pub fn load(workspace: &Path) -> Arc<Self> {
        let wake: Waker = Arc::new(|| {});
        let cache = ImageCache::new(wake);
        let root = sprite_root(workspace);
        let sets: [(Set, Set); CAPTAIN_NAMES.len()] =
            std::array::from_fn(|captain| portraits(&cache, captain, root.as_deref()));
        let [(c0, s0), (c1, s1), (c2, s2), (c3, s3)] = sets;
        let (crew, small) = ([c0, c1, c2, c3], [s0, s1, s2, s3]);
        let mark_dark = mark(&cache, true);
        let mark = mark(&cache, false);
        // Startup only. Decode off-thread before the first frame, including headless fixtures.
        for image in crew
            .iter()
            .chain(&small)
            .flatten()
            .chain([&mark, &mark_dark])
        {
            image.wait().expect("valid crew artwork");
        }
        Arc::new(Self {
            crew,
            small,
            mark,
            mark_dark,
        })
    }

    pub fn face(&self, captain: usize, face: Face) -> &Image {
        &self.crew[captain.min(CAPTAIN_NAMES.len() - 1)][face.index()]
    }

    /// The head crop for small tiles. Drop-in sets without crops reuse the full bust.
    pub fn small_face(&self, captain: usize, face: Face) -> &Image {
        &self.small[captain.min(CAPTAIN_NAMES.len() - 1)][face.index()]
    }
}

/// An explicit drop-in folder wins over the workspace folder. Neither is required.
fn sprite_root(workspace: &Path) -> Option<PathBuf> {
    env::var_os("SHINA_SPRITES")
        .map(PathBuf::from)
        .filter(|path| path.is_dir())
        .or_else(|| {
            let local = workspace.join("assets").join("crew");
            local.is_dir().then_some(local)
        })
}

fn portraits(cache: &ImageCache, captain: usize, root: Option<&Path>) -> (Set, Set) {
    let loaded = root.and_then(|root| load_set(cache, root, captain));
    loaded.unwrap_or_else(|| embedded(cache, captain))
}

/// A set is either the named folder or the numeric captain index. All six faces must
/// decode as files before the whole set is accepted.
fn load_set(cache: &ImageCache, root: &Path, captain: usize) -> Option<(Set, Set)> {
    let folders = [
        root.join(CAPTAIN_KEYS[captain]),
        root.join(captain.to_string()),
    ];
    for folder in folders {
        if !folder.is_dir() {
            continue;
        }
        let mut images = Vec::with_capacity(Face::COUNT);
        let mut crops = Vec::with_capacity(Face::COUNT);
        for name in FACE_FILES {
            let bytes = std::fs::read(folder.join(format!("{name}.png"))).ok()?;
            let image = cache.load(bytes);
            image.wait().ok()?;
            // An optional `<Face>.small.png` head crop; otherwise small tiles use the bust.
            let crop = std::fs::read(folder.join(format!("{name}.small.png")))
                .ok()
                .map(|bytes| cache.load(bytes))
                .filter(|crop| crop.wait().is_ok())
                .unwrap_or_else(|| image.clone());
            images.push(image);
            crops.push(crop);
        }
        if let (Ok(set), Ok(small)) = (Set::try_from(images), Set::try_from(crops)) {
            return Some((set, small));
        }
    }
    None
}

fn embedded(cache: &ImageCache, captain: usize) -> (Set, Set) {
    macro_rules! set {
        ($name:literal) => {
            (
                [
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Normal.png")).as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Happy.png")).as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Determined.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Surprised.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Dizzy.png")).as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Sad.png")).as_slice(),
                    ),
                ],
                [
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Normal.small.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Happy.small.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Determined.small.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Surprised.small.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Dizzy.small.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Sad.small.png"))
                            .as_slice(),
                    ),
                ],
            )
        };
    }
    match captain {
        0 => set!("ember"),
        1 => set!("juniper"),
        2 => set!("sable"),
        _ => set!("pip"),
    }
}

/// A small original pixel mark: a dark crew badge with a cream "S" and three service dots.
fn mark(cache: &ImageCache, light: bool) -> Image {
    const SIZE: usize = 24;
    let mut rgba = vec![0u8; SIZE * SIZE * 4];
    let mut put = |x: usize, y: usize, color: [u8; 4]| {
        let at = (y * SIZE + x) * 4;
        rgba[at..at + 4].copy_from_slice(&color);
    };
    let (ink, cream) = if light {
        ([236, 236, 238, 255], [30, 30, 32, 255])
    } else {
        ([35, 35, 31, 255], [244, 239, 227, 255])
    };
    let green = [143, 188, 106, 255];
    let orange = [224, 122, 84, 255];
    let blue = [106, 168, 200, 255];
    for y in 0..SIZE {
        for x in 0..SIZE {
            let corner_x = x.clamp(5, SIZE - 6);
            let corner_y = y.clamp(5, SIZE - 6);
            let dx = x as i32 - corner_x as i32;
            let dy = y as i32 - corner_y as i32;
            if dx * dx + dy * dy <= 25 {
                put(x, y, ink);
            }
        }
    }
    const S: [&str; 7] = [
        "01110", "10000", "10000", "01110", "00001", "00001", "01110",
    ];
    for (row, bits) in S.iter().enumerate() {
        for (column, bit) in bits.bytes().enumerate() {
            if bit != b'0' {
                for dy in 0..2 {
                    for dx in 0..2 {
                        put(7 + column * 2 + dx, 5 + row * 2 + dy, cream);
                    }
                }
            }
        }
    }
    for (offset, color) in [(7, green), (11, orange), (15, blue)] {
        put(offset, 20, color);
        put(offset + 1, 20, color);
        put(offset, 21, color);
        put(offset + 1, 21, color);
    }
    let image = cache.rgba(SIZE as u32, SIZE as u32, rgba);
    image.wait().expect("valid generated crew mark");
    image
}
